# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" rx="14" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">Lafzatullahtaki (اللّٰه) Lâm Harfinin Okunuş Hükümleri</text>\n  <rect x="35" y="48" width="300" height="190" rx="10" fill="#fef3c7" stroke="#f59e0b" stroke-width="2"/>\n  <text x="185" y="74" text-anchor="middle" font-size="14" font-weight="bold" fill="#b45309">1. Kalın Okunuş (Tefhîm / التفخيم)</text>\n  <text x="185" y="98" text-anchor="middle" font-size="11" fill="#78350f">Lafzatullahtan önceki harfin harekesi:</text>\n  <rect x="60" y="108" width="250" height="36" rx="6" fill="#ffffff" stroke="#fbbf24"/>\n  <text x="185" y="131" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Üstün (ـَ) veya Ötre (ـُ) ise Kalın Okunur</text>\n  <text x="185" y="168" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Örnekler: هُوَ اللّٰهُ  |  نَصْرُ اللّٰهِ</text>\n  <text x="185" y="192" text-anchor="middle" font-size="11" fill="#78350f">Hüvallâh (Üstün) | Nasrullâh (Ötre)</text>\n  <text x="185" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Dil kökü damağa yükselerek tok ses verir</text>\n  <rect x="365" y="48" width="300" height="190" rx="10" fill="#ecfdf5" stroke="#10b981" stroke-width="2"/>\n  <text x="515" y="74" text-anchor="middle" font-size="14" font-weight="bold" fill="#047857">2. İnce Okunuş (Terkîk / الترقيق)</text>\n  <text x="515" y="98" text-anchor="middle" font-size="11" fill="#065f46">Lafzatullahtan önceki harfin harekesi:</text>\n  <rect x="390" y="108" width="250" height="36" rx="6" fill="#ffffff" stroke="#34d399"/>\n  <text x="515" y="131" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">Esre (ـِ) ise İnce Okunur</text>\n  <text x="515" y="168" text-anchor="middle" font-size="13" font-weight="bold" fill="#047857">Örnekler: بِسْمِ اللّٰهِ  |  لِلّٰهِ  |  فِي سَبِيلِ اللّٰهِ</text>\n  <text x="515" y="192" text-anchor="middle" font-size="11" fill="#065f46">Bismillâh | Lillâh | Fî sebîlillâh</text>\n  <text x="515" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#047857">Dil ucu üst diş etlerine değerek ince okunur</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" rx="14" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">Râ (ر) Harfinin Okunuş Hükümleri (Ahkâmü\'r-Râ)</text>\n  <rect x="30" y="48" width="205" height="190" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.8"/>\n  <text x="132" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kalın Okunduğu Durumlar</text>\n  <text x="132" y="96" text-anchor="middle" font-size="11" fill="#1e3a8a">• Râ üstün veya ötreli ise</text>\n  <text x="132" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">• Râ sakin, öncesi üstün/ötre ise</text>\n  <text x="132" y="136" text-anchor="middle" font-size="11" fill="#1e3a8a">• Ârızî kesreden sonra gelirse</text>\n  <text x="132" y="156" text-anchor="middle" font-size="11" fill="#1e3a8a">• İstîlâ harfinden önce gelirse</text>\n  <rect x="45" y="172" width="175" height="50" rx="6" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="132" y="194" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">رَبَّنَا | يَرْزُقُ | مِرْصَادًا</text>\n  <text x="132" y="212" text-anchor="middle" font-size="10" fill="#1e40af">Rabbenâ, Yerzuku, Mirsâdâ</text>\n  <rect x="248" y="48" width="205" height="190" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İnce Okunduğu Durumlar</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" fill="#166534">• Râ esreli (kesreli) ise</text>\n  <text x="350" y="116" text-anchor="middle" font-size="11" fill="#166534">• Râ sakin, öncesi aslî esre ise</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#166534">• Sakin yâ (يْ) harfinden sonra</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#166534">durak yapılarak sakin okunursa</text>\n  <rect x="263" y="172" width="175" height="50" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="350" y="194" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">رِزْقًا | فِرْعَوْنَ | خَيْرٌ</text>\n  <text x="350" y="212" text-anchor="middle" font-size="10" fill="#166534">Rizkan, Fir\'avne, Hayr</text>\n  <rect x="465" y="48" width="205" height="190" rx="10" fill="#fdf4ff" stroke="#a855f7" stroke-width="1.8"/>\n  <text x="567" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Her İki Vecih Câiz Olanlar</text>\n  <text x="567" y="96" text-anchor="middle" font-size="11" fill="#6b21a8">• Sakin râ\'dan önce esre, sonra</text>\n  <text x="567" y="116" text-anchor="middle" font-size="11" fill="#6b21a8">esreli istîlâ harfi bulunduğunda</text>\n  <text x="567" y="136" text-anchor="middle" font-size="11" fill="#6b21a8">• İstîlâ harfinden sonra durulup</text>\n  <text x="567" y="156" text-anchor="middle" font-size="11" fill="#6b21a8">râ harfi sakin kılındığında</text>\n  <rect x="480" y="172" width="175" height="50" rx="6" fill="#ffffff" stroke="#d8b4fe"/>\n  <text x="567" y="194" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">فِرْقٍ | مِصْرَ | الْقِطْرِ</text>\n  <text x="567" y="212" text-anchor="middle" font-size="10" fill="#6b21a8">Firkın, Mısr, El-Kıtr</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" rx="14" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">Tenvin ile Biten KelimeLafzatullaha Bağlanırken (Vasıl) Okunuş</text>\n  <rect x="40" y="50" width="620" height="85" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.8"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kural: Tenvindeki Sakin Nûn (نْ), Geçişte Esre (Kesre) İle Harekelendirilir (Nûn-i Kutnî)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" fill="#1e3a8a">Tenvinli kelimeden sonra Lafzatullah geldiğinde iki sakin harf yan yana gelemez.</text>\n  <text x="350" y="118" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Tenvin نِ (ni) sesine dönüştüğü için Lafzatullah esreden sonra gelmiş olur ve İNCE okunur!</text>\n  <rect x="40" y="150" width="295" height="90" rx="10" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="187" y="175" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Ayrı Okunuş (Vakıf ve İbtidâ)</text>\n  <text x="187" y="200" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">قُلْ هُوَ اللّٰهُ أَحَدٌ \u06dd اللّٰهُ الصَّمَدُ</text>\n  <text x="187" y="222" text-anchor="middle" font-size="11" fill="#7f1d1d">"Ehad" diye durulursa "Allâhü\'s-samed" KALIN başlanır</text>\n  <rect x="365" y="150" width="295" height="90" rx="10" fill="#ecfdf5" stroke="#10b981" stroke-width="1.5"/>\n  <text x="512" y="175" text-anchor="middle" font-size="13" font-weight="bold" fill="#065f46">Birleştirerek Okunuş (Vasıl Hali)</text>\n  <text x="512" y="200" text-anchor="middle" font-size="13" font-weight="bold" fill="#047857">أَحَدٌ اللّٰهُ ← أَحَدُنِ اللّٰهُ الصَّمَدُ</text>\n  <text x="512" y="222" text-anchor="middle" font-size="11" fill="#065f46">"Ehadünillâhü\'s-samed" şeklinde İNCE bağlanır</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
